void Solver::bump_var(int var, double coeff) {
    // Compute increment and update activity
    double inc = var_inc * coeff;
    activity[var] += inc;

    // Rescale all activities if any exceeds a safe threshold to avoid overflow
    const double ACT_LIMIT = 1e150;
    if (activity[var] > ACT_LIMIT) {
        double scale = 1e-150;
        for (int i = 1; i <= vars; ++i) {
            activity[i] *= scale;
        }
        var_inc *= scale;
    }

    // Ensure the variable is correctly positioned in the VSIDS heap
    if (vsids.inHeap(var)) {
        vsids.update(var);
    } else {
        vsids.insert(var);
    }
}
